// Minimal env-file parser. Covers the dotenv-style subset this service uses:
// comments, blank lines, optional `export`, and single/double quoted values.
// Malformed lines throw rather than being silently skipped.

const KEY = /^[A-Za-z_][A-Za-z0-9_]*$/;

const ESCAPES: Record<string, string> = {
  n: "\n",
  r: "\r",
  t: "\t",
  "0": "\0",
};

const isBlank = (c: string) => c === " " || c === "\t" || c === "\r";

export function parseEnvFile(text: string): Record<string, string> {
  const src = text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
  const out: Record<string, string> = {};
  let i = 0;
  let line = 1;

  const fail = (msg: string): never => {
    throw new Error(`env line ${line}: ${msg}`);
  };

  // Advance past the rest of the current line, including its newline.
  const skipLine = () => {
    while (i < src.length && src[i] !== "\n") i++;
    if (i < src.length) {
      line++;
      i++;
    }
  };

  while (i < src.length) {
    const c = src[i];
    if (c === "\n") {
      line++;
      i++;
      continue;
    }
    if (isBlank(c)) {
      i++;
      continue;
    }
    if (c === "#") {
      skipLine();
      continue;
    }

    const keyStart = i;
    while (i < src.length && src[i] !== "=" && src[i] !== "\n") i++;
    if (i >= src.length || src[i] === "\n") fail(`expected KEY=value, got ${JSON.stringify(src.slice(keyStart, i))}`);
    let key = src.slice(keyStart, i).trim();
    i++; // consume '='
    if (key.startsWith("export ")) key = key.slice("export ".length).trim();
    if (!KEY.test(key)) fail(`invalid key ${JSON.stringify(key)}`);

    while (i < src.length && isBlank(src[i])) i++;

    const quote = src[i];
    if (quote === '"' || quote === "'") {
      i++;
      let value = "";
      for (;;) {
        if (i >= src.length) fail(`unterminated ${quote} quote`);
        const ch = src[i];
        if (ch === quote) {
          i++;
          break;
        }
        if (ch === "\\" && quote === '"') {
          i++;
          if (i >= src.length) fail("unterminated escape");
          value += ESCAPES[src[i]] ?? src[i];
          if (src[i] === "\n") line++;
          i++;
          continue;
        }
        if (ch === "\n") line++;
        value += ch;
        i++;
      }
      out[key] = value;
      while (i < src.length && isBlank(src[i])) i++;
      if (i < src.length && src[i] !== "\n" && src[i] !== "#") {
        fail(`unexpected text after closing quote for ${key}`);
      }
      skipLine();
    } else {
      let value = "";
      while (i < src.length && src[i] !== "\n") {
        // An unquoted '#' starts a comment when it follows whitespace.
        if (src[i] === "#" && (value === "" || isBlank(src[i - 1]))) break;
        value += src[i];
        i++;
      }
      out[key] = value.trimEnd();
      skipLine();
    }
  }

  return out;
}

