import { test } from "node:test";
import assert from "node:assert/strict";
import { parseEnvFile } from "../src/env.ts";

test("skips comments and blank lines", () => {
  assert.deepEqual(parseEnvFile("# note\n\n  \nPORT=8080\n"), { PORT: "8080" });
});

test("keeps a hash inside quotes", () => {
  assert.deepEqual(parseEnvFile("MOTD='hello # not a comment'\n"), { MOTD: "hello # not a comment" });
  assert.deepEqual(parseEnvFile('MOTD="hello # not a comment"\n'), { MOTD: "hello # not a comment" });
});

test("strips an unquoted inline comment but not a bare hash", () => {
  assert.deepEqual(parseEnvFile("HOST=0.0.0.0  # the bind address\n"), { HOST: "0.0.0.0" });
  assert.deepEqual(parseEnvFile("TAG=build#42\n"), { TAG: "build#42" });
});

test("keeps spaces inside quotes and trims unquoted values", () => {
  assert.deepEqual(parseEnvFile('APP_NAME="Order Service"\n'), { APP_NAME: "Order Service" });
  assert.deepEqual(parseEnvFile("APP_NAME=  order-service  \n"), { APP_NAME: "order-service" });
});

test("expands escapes in double quotes only", () => {
  assert.deepEqual(parseEnvFile('A="one\\ntwo"\n'), { A: "one\ntwo" });
  assert.deepEqual(parseEnvFile("A='one\\ntwo'\n"), { A: "one\\ntwo" });
  assert.deepEqual(parseEnvFile('A="say \\"hi\\""\n'), { A: 'say "hi"' });
});

test("accepts an export prefix and a comment after a quoted value", () => {
  assert.deepEqual(parseEnvFile('export APP_NAME="Order Service" # why\n'), { APP_NAME: "Order Service" });
});

test("handles CRLF files and a missing trailing newline", () => {
  assert.deepEqual(parseEnvFile("PORT=8080\r\nHOST=db.internal"), { PORT: "8080", HOST: "db.internal" });
});

test("allows empty values", () => {
  assert.deepEqual(parseEnvFile("A=\nB=''\n"), { A: "", B: "" });
});

test("rejects malformed lines", () => {
  assert.throws(() => parseEnvFile("PORT 8080\n"), /expected KEY=value/);
  assert.throws(() => parseEnvFile("2PORT=8080\n"), /invalid key/);
  assert.throws(() => parseEnvFile('A="unterminated\n'), /unterminated/);
  assert.throws(() => parseEnvFile('A="quoted" junk\n'), /unexpected text after closing quote/);
});

